package com.bank.blockingdeque;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class BlockingDequeTest {

    @Test
    void putAndTake_bothEnds() throws InterruptedException {
        LinkedBlockingDeque<String> deque = new LinkedBlockingDeque<>(10);
        deque.putFirst("A");
        deque.putLast("B");
        deque.putLast("C");

        assertThat(deque.takeFirst()).isEqualTo("A");  // head
        assertThat(deque.takeLast()).isEqualTo("C");   // tail
        assertThat(deque.takeFirst()).isEqualTo("B");  // remaining
    }

    @Test
    void bounded_offerReturnsFalse() {
        LinkedBlockingDeque<String> deque = new LinkedBlockingDeque<>(2);
        assertThat(deque.offerFirst("A")).isTrue();
        assertThat(deque.offerLast("B")).isTrue();
        assertThat(deque.offerFirst("C")).isFalse();  // full!
    }

    @Test
    void workStealing_simulation() throws InterruptedException {
        LinkedBlockingDeque<String> workerDeque = new LinkedBlockingDeque<>();
        workerDeque.putLast("TASK-1");
        workerDeque.putLast("TASK-2");
        workerDeque.putLast("TASK-3");

        // Worker takes from HEAD:
        assertThat(workerDeque.pollFirst()).isEqualTo("TASK-1");
        // Thief steals from TAIL:
        assertThat(workerDeque.pollLast()).isEqualTo("TASK-3");
        // No contention — opposite ends!
    }
}
